class TrieNode { constructor(){ this.next = new Map(); this.pass = 0; this.end = 0; } }
class TrieDict { constructor(){ this.root = new TrieNode(); }
 insertWord(w){ let p=this.root; for(const ch of w){ if(!p.next.has(ch)) p.next.set(ch,new TrieNode()); p=p.next.get(ch); p.pass++; } p.end++; }
 deleteWord(w){ let stack=[]; let p=this.root; stack.push(p); for(const ch of w){ if(!p.next.has(ch)) return; p=p.next.get(ch); stack.push(p); } if(p.end>0){ p.end--; for(let i=w.length-1;i>=0;i--){ const ch=w[i]; const node=stack[i+1]; node.pass--; if(node.pass===0){ stack[i].next.delete(ch);} else break; } } }
 countWordsWithPrefix(pfx){ let p=this.root; for(const ch of pfx){ if(!p.next.has(ch)) return 0; p=p.next.get(ch); } return p.end; }
 } 
